importScripts('opencv.js','matcher.js');
let cvReady=new Promise((resolve,reject)=>{try{if(cv.Mat)resolve({engine:cv});else if(cv.then)cv.then(m=>resolve({engine:m}));else cv.onRuntimeInitialized=()=>resolve({engine:cv})}catch(e){reject(e)}});
const cache=new Map();
self.onmessage=async ({data})=>{const {request,type}=data;try{const {engine}=await cvReady;if(type==='ready'){postMessage({request,ok:true});return}if(type==='clear'){cache.clear();postMessage({request,ok:true});return}if(type==='extract'){cache.set(data.id,RobustMatcher.extract(engine,new Uint8Array(data.rgba),data.width,data.height));postMessage({request,ok:true});return}if(type==='rank'){const ranks=[];const total=data.docs.length*data.uploads.length;let done=0;for(const id of data.docs){let row=[];for(let index=0;index<data.uploads.length;index++){row.push({...RobustMatcher.compare(engine,cache.get(id),cache.get(data.uploads[index])),index});done++;if(done%15===0)postMessage({progress:done,total})}row.sort((a,b)=>b.score-a.score);ranks.push(row)}postMessage({request,ranks});return}throw Error('Unknown matching operation')}catch(e){postMessage({request,error:typeof e==='number'?'Image analysis failed. Try smaller images.':e.message||String(e)})}};
